check_code:
s=[81,65,50]
opts={'A':37,'B':34,'C':35,'D':36}
def ok(v):
    t=s+[v,23,11]
    d=[t[i]-t[i+1] for i in range(5)]
    return all(d[i]-d[i+1]==1 for i in range(4))
assert [k for k,v in opts.items() if ok(v)]==['D']

opts={'A':'RTTUWW','B':'NOPPSS','C':'ACCDFF','D':'IKKLNN'}
def p(w):
    return tuple(ord(w[i+1])-ord(w[i]) for i in range(5))
odd=[k for k,v in opts.items() if sum(p(v)==p(x) for x in opts.values())==1]
assert odd==['B']

def f(w):
    return ''.join(chr((ord(c)-65+s)%26+65) for c,s in zip(w,[4,3,2,1]))
assert f('BAKE')=='FDMF' and f('TURN')=='XXTO'
r=f('MOCK')
opts={'A':'RQGL','B':'QREL','C':'QSEL','D':'RRFL'}
assert r==opts['B']
assert all(r!=v for k,v in opts.items() if k!='B')

def nxt(w,n):
    return chr(ord(w[0])-2)+chr(ord(w[1])-2)+' '+str(n-4)
assert nxt('MY',84)=='KW 80' and nxt('KW',80)=='IU 76' and nxt('IU',76)=='GS 72'
r=nxt('GS',72)
opts={'A':'FP 69','B':'EQ 68','C':'ER 70','D':'FQ 71'}
assert r==opts['B']
assert all(r!=v for k,v in opts.items() if k!='B')

def n(w):
    return ''.join(chr((ord(c)-65+s)%26+65) for c,s in zip(w,[-2,2,-2,2]))
assert n('XJUM')=='VLSO' and n('VLSO')=='TNQQ' and n('TNQQ')=='RPOS'
r=n('RPOS')
opts={'A':'PRMT','B':'QRMT','C':'PRNU','D':'PRMU'}
assert r==opts['D']
assert all(r!=v for k,v in opts.items() if k!='D')

units={'Frequency':'Hertz','Power':'Watt','Resistance':'Ohm','Illuminance':'Lux','Force':'Newton'}
opts={'A':('Power','Newton'),'B':('Resistance','Candela'),'C':('Illuminance','Lux'),'D':('Force','Volt')}
ok=[k for k,(a,b) in opts.items() if units[a]==b]
assert ok==['C']
